import unittest

class TestShippingFee(unittest.TestCase):
    def test_negative_totals(self):
        with self.assertRaises(ValueError):
            shipping_fee(-1.0, expedited=False)
        with self.assertRaises(ValueError):
            shipping_fee(-0.01, expedited=True)

    def test_zero_total(self):
        self.assertEqual(shipping_fee(0.0, expedited=False), 5.0)
        self.assertEqual(shipping_fee(0.0, expedited=True), 12.0)

    def test_just_below_fifty(self):
        self.assertEqual(shipping_fee(49.99, expedited=False), 5.0)
        self.assertEqual(shipping_fee(49.99, expedited=True), 12.0)

    def test_exactly_fifty(self):
        self.assertEqual(shipping_fee(50.0, expedited=False), 0.0)
        self.assertEqual(shipping_fee(50.0, expedited=True), 7.0)

    def test_above_fifty(self):
        self.assertEqual(shipping_fee(50.01, expedited=False), 0.0)
        self.assertEqual(shipping_fee(50.01, expedited=True), 7.0)
        self.assertEqual(shipping_fee(100.0, expedited=False), 0.0)
        self.assertEqual(shipping_fee(100.0, expedited=True), 7.0)

    def test_default_expedited_parameter(self):
        self.assertEqual(shipping_fee(25.0), 5.0)
        self.assertEqual(shipping_fee(50.0), 0.0)

if __name__ == '__main__':
    unittest.main()
